// Markdown rendering for Premium Report sections.
//
// Report prose is generated by an LLM from retrieved knowledge-base evidence,
// so it is treated as untrusted content: it is parsed as Markdown (never
// injected as raw HTML), and the resulting HTML is then sanitized with
// DOMPurify before it ever reaches dangerouslySetInnerHTML. Both steps
// matter — marked alone will happily pass through an inline <script> or an
// onerror= attribute written in the source Markdown.
import { marked } from 'marked';
import DOMPurify from 'dompurify';

// GFM gives us the tables the report blueprint's structured sections use
// (planetary positions, dasha periods). `breaks` is off: the generator emits
// real paragraph breaks, and turning single newlines into <br> would shred
// the long-form prose this viewer exists to make readable.
marked.setOptions({ gfm: true, breaks: false });

// The report format's actual vocabulary, nothing more. Anything outside this
// list is dropped rather than escaped, so a malformed or hostile construct
// cannot survive as visible markup.
const ALLOWED_TAGS = [
  'p', 'br', 'hr',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
  'strong', 'em', 'b', 'i', 'u', 's', 'del', 'mark',
  'ul', 'ol', 'li',
  'blockquote', 'code', 'pre',
  'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td',
  'a', 'span', 'div', 'sup', 'sub',
];

// No `style` (CSS can position an element over the rest of the page) and no
// event handlers. `href` is allowed but constrained by the hook below.
const ALLOWED_ATTR = ['href', 'title', 'colspan', 'rowspan', 'align', 'start', 'class'];

let hooksInstalled = false;

function installHooks() {
  if (hooksInstalled) return;
  hooksInstalled = true;
  // Any link the generator produces points outward, so open it in a new tab
  // and cut the opener reference. Added as a hook rather than a string
  // rewrite so it applies to the parsed DOM, after sanitization has already
  // decided the node is allowed to exist at all.
  DOMPurify.addHook('afterSanitizeAttributes', node => {
    if (node.tagName === 'A' && node.hasAttribute('href')) {
      node.setAttribute('target', '_blank');
      node.setAttribute('rel', 'noopener noreferrer nofollow');
    }
  });
}

/**
 * Parses report Markdown and returns sanitized HTML safe to inject.
 * Returns an empty string for empty/missing content so callers can render a
 * real "this section has no content" state instead of a blank block.
 */
export function renderReportMarkdown(markdown: string | null | undefined): string {
  if (!markdown || !markdown.trim()) return '';
  installHooks();
  const rawHtml = marked.parse(markdown, { async: false }) as string;
  return DOMPurify.sanitize(rawHtml, {
    ALLOWED_TAGS,
    ALLOWED_ATTR,
    // Belt and braces alongside the tag allowlist: even if <style>/<form>
    // were somehow permitted, these keep them out.
    FORBID_TAGS: ['style', 'script', 'iframe', 'object', 'embed', 'form', 'input', 'button'],
    FORBID_ATTR: ['style', 'onerror', 'onload', 'onclick'],
    // Only real document links. Blocks javascript:, data: and vbscript: URLs.
    ALLOWED_URI_REGEXP: /^(?:https?:|mailto:|#)/i,
  });
}

/**
 * Plain-text preview of a section, for the table of contents and list cards.
 * Deliberately strips Markdown syntax rather than rendering it — a heading's
 * `##` or a table's pipes read as noise at preview size.
 */
export function markdownPreview(markdown: string | null | undefined, maxLength = 160): string {
  if (!markdown) return '';
  const text = markdown
    .replace(/```[\s\S]*?```/g, ' ')      // fenced code
    .replace(/^\s{0,3}#{1,6}\s+/gm, '')   // heading markers
    .replace(/^\s{0,3}[>*-]\s+/gm, '')    // quotes and list bullets
    .replace(/\|/g, ' ')                  // table pipes
    .replace(/[*_`~]/g, '')               // emphasis marks
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // links -> their text
    .replace(/\s+/g, ' ')
    .trim();
  return text.length <= maxLength ? text : `${text.slice(0, maxLength - 1).trimEnd()}…`;
}
